sp_widget.client_script:
api.controller=function($scope, $window, $rootScope) {
  /* widget controller */
  var c = this;

	  $scope.contrastIsActive = false;

    var contrastListener = $rootScope.$on('sp.contrast.toggled', function(event, data) {
        $scope.contrastIsActive = data.enabled; 
        //updateImageContrast(data.enabled);
    });

    $scope.$on('$destroy', contrastListener);


};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;600;700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Roboto+Flex:opsz,wght@8..144,100..1000&display=swap');


// ----------------------------------------------------
// DEFINIÇÃO DE VARIÁVEIS DE COR E ESTRUTURAIS
// ----------------------------------------------------
$primary-color: #4773C6; // Cor do Título Principal (data.titulo)
$title-color: #293273; // Cor do Título do Card
$description-color: #333333; // Cor da Descrição
$bg-color: #ffffff; // Fundo esticado (branco)

// Variáveis estruturais
$content-max-width: 1200px;
$card-border-radius: 8px;
$card-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
$card-hover-shadow: 0 8px 15px rgba(0, 0, 0, 0.15);
$icon-circle-size: 45px;

// ----------------------------------------------------
// 1. CONTAINER FULL-WIDTH E BACKGROUND ESTICADO
// ----------------------------------------------------
.panel.dashboard-widget {
    border: none;
    box-shadow: none;
    margin-bottom: 0;

    // APLICAÇÃO DA FONTE PRINCIPAL (Poppins)
    font-family: 'Poppins', sans-serif;

    // Aplica o background branco
    background-color: $bg-color; 
    padding-top: 30px; 
    padding-bottom: 30px;
}

// ----------------------------------------------------
// 2. WRAPPER DE CONTEÚDO CENTRALIZADO E LIMITADO
// ----------------------------------------------------
.content-wrapper {
    max-width: $content-max-width;
    margin: 0 auto; 
    padding: 0 15px; 
}


// ----------------------------------------------------
// 3. ESTILOS DO TÍTULO E CARDS
// ----------------------------------------------------

.panel-heading {
    background-color: transparent;
    border-bottom: none;
    padding-top: 0;
    padding-bottom: 20px;

    .panel-title {
        color: $primary-color; 
        font-weight: 700; // Poppins Bold para destaque
        font-size: 2.4rem;
        text-align: center;
      	font-family: "Roboto Flex", sans-serif;
    }
}

// Configuração do Grid (Flexbox para altura igual)
.row.cards-row {
    display: flex;
    flex-wrap: wrap; 
    margin-left: -10px; 
    margin-right: -10px;
}

.card-col {
    display: flex; 
    padding-left: 10px; 
    padding-right: 10px;
    margin-bottom: 20px; 
}

.widget-card {
    display: flex; 
    width: 100%; 
    text-decoration: none !important; 
    color: inherit;
    padding: 0;
}

// O conteúdo do card (Centralização Horizontal e Layout Vertical)
.card-content {
    width: 100%;
    height: 100%; 

    display: flex;
    flex-direction: column; 
    align-items: center; 
    text-align: center; 

    background-color: #ffffff;
    border-radius: $card-border-radius;
    padding: 25px 20px;
    box-shadow: $card-shadow;
    border: 1px solid #f0f0f0;
    transition: transform 0.3s ease, box-shadow 0.3s ease;

    &:hover {
        transform: translateY(-5px); 
        box-shadow: $card-hover-shadow;
    }
}

// ----------------------------------------------------
// 4. ESTILOS DA IMAGEM/ÍCONE (COM FUNDO REDONDO)
// ----------------------------------------------------

.icon-container {
    display: flex;
    align-items: center;
    justify-content: center;
    width: $icon-circle-size;
    height: $icon-circle-size;
    border-radius: 50%;
    background-color: lighten($primary-color, 40%);
    color: $primary-color; 

    margin-bottom: 15px;

    .card-image-asset {
        max-width: 60%; 
        max-height: 60%;
        height: auto;
        display: block;
    }
}

.card-title {
    h4 {
        color: $title-color; 
        font-weight: 600; // Poppins Semi-Bold
        margin-top: 5px; 
        margin-bottom: 10px;
    }
}

.card-description {
    p {
        color: $description-color; 
        // Usando Roboto Flex para o corpo do texto para dar variedade e legibilidade
        font-family: 'Poppins', sans-serif; 
        font-weight: 400; 
        font-size: 0.9em;
        line-height: 1.4;
        margin-bottom: 0;
    }
}


// ----------------------------------------------------
// ESTILOS DE ACESSIBILIDADE - MODO CONTRASTE
// ----------------------------------------------------

.contrast-active {
    // Título Principal ({{data.titulo}})
    .panel-heading .panel-title {
        color: #ffffff !important; // Cor branca para o título principal
    }

    // Título do Card ({{item.titulo}})
    .card-title h4 {
        color: #ffffff !important; // Cor branca para o título do card
    }

    // Descrição do Card ({{item.descricao}})
    .card-description p {
        color: #ffffff !important; // Cor branca para a descrição
    }

    // Opcional: Ajuste o fundo do card para um contraste melhor
    .widget-card .card-content {
        background-color: #000000; // Por exemplo, fundo preto
        border-color: #ffffff; // Borda branca
        box-shadow: none; // Remove a sombra
    }

    // Opcional: Ajuste o fundo do container principal para contraste
    &.dashboard-widget {
        background-color: #000000 !important; // Fundo preto no widget
      	border-radius: 0 !important;
    }
}

